SourceCode.Declaration:
/// <summary>
/// The class <c>GUPEcoResPricingAttribute</c> is used to denote a pricing attribute impl. by EcoResAttribute.
/// </summary>
internal class METGUPPricingAttributeEcoResAttribute extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
    private GUPIPricingAttributeProvider attributeProvider;
    private Name name;
    private Name typeName;
    EcoResAttributeType ecoResAttributeType;

}

Method.Source:
[SuppressBPWarning('BPErrorClassNewNotProtected', 'External class should be able to call constructor.')]
public void new(Name _name, Name _typeName, GUPIPricingAttributeProvider _attributeProvider)
{
    this.name = _name;
    this.typeName = _typeName;
    this.attributeProvider = _attributeProvider;
    this.hashString = strFmt('%1 %2', this.getEcoResAttributeProviderId(), this.getAttributeKey());
    this.hashCode = this.hashString.GetHashCode();
}

public static str createAttributeKey(str _attributeName, str _attributeTypeName)
{
    return _attributeName + '_' + _attributeTypeName;
}

public GUPPricingAttributeSourceLevel getSourceLevel()
{
    DictClass dc = new DictClass(classIdGet(attributeProvider));
    return (dc.getAttribute('GUPPricingAttributeSourceDiscoveryAttribute') as GUPPricingAttributeSourceDiscoveryAttribute).parmLevel();
}

public anytype getValueOfAttribute(Common _pricingObject) //_pricingObject == SO,PO,SQ
{
    return this.attributeProvider.getValueOfAttribute(_pricingObject, this);
}

public str getName() // color, product category, customer category, customer classification
{
    return this.name;
}

public str getAttributeKey()
{
    return this.name + '_' + this.typeName;
}

private EcoResAttributeType getEcoResAttributeType()
{
    if (!this.ecoResAttributeType || this.ecoResAttributeType.Name != this.typeName)
    {
        this.ecoResAttributeType = EcoResAttributeType::findByName(this.typeName);
    }

    return this.ecoResAttributeType;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qbdsMap = null)
{
    return this.attributeProvider.buildPricingObjectQuery(_query, this, _value, _qbdsMap);
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    // Do nothing here for customized pricing attribute.
    // Range set in buildPricingObjectQuery().
}

public static boolean IsAttributeDataTypeAllowed(AttributeDataType _dataType)
{
    switch (_dataType)
    {
        case AttributeDataType::Decimal:
        case AttributeDataType::Integer:
        case AttributeDataType::Text:
        case AttributeDataType::TrueFalse:
            return true;
        default:
            return false;
    }
}

public static str convertValue2Str(anytype _value, AttributeDataType _dataType)
{
    switch (_dataType)
    {
        case AttributeDataType::Decimal:
            return num2Str(_value, 0, 3, 1, 2);
        case AttributeDataType::Integer:
            return int642Str(_value);
        case AttributeDataType::Text:
            return _value;
        case AttributeDataType::TrueFalse:
            return enum2Str(_value);
        default:
            throw error(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeEcoResAttribute_AttributeTypeNotSupport",enum2Str(_dataType)));
    }
}
